print("📌 Available Variables: `df`, `X` (Numpy array for clustering)\\n")
print("🔍 Preview First 3 Rows of `df`:")
display(df.head(3))
"""

    else:
        # Dùng dataset dự phòng nếu input bị lỗi hay bị gì đó
        return f"""# ==============================================================================
